def find_zero(xs: list):
    if len(xs) % 2 != 0:
        raise ValueError("xs must have an even number of coefficients")

    # Find the largest non-zero coefficient
    max_coeff = max(abs(coeff) for coeff in xs)

    # Use the bisection method to find a zero point
    def bisect(left, right):
        mid = (left + right) / 2.0
        if abs(poly(xs, mid)) < 1e-6:
            return round(mid, 2)
        elif poly(xs, left) * poly(xs, mid) > 0:
            return bisect(mid, right)
        else:
